<?php
require __DIR__.'/config.php';
$page=$_GET['page']??(empty($_SESSION['user_id'])?'login':'dashboard');
if($page==='logout'){session_destroy();go('login');}
if($page==='register' && $_SERVER['REQUEST_METHOD']==='POST'){
 $count=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
 if($count>0){flash('An account already exists. Ask your administrator to add staff accounts.','error');go('login');}
 $name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$pw=$_POST['password']??'';
 if($name&&$username&&strlen($pw)>=6){$s=$pdo->prepare('INSERT INTO users(name,username,password,role) VALUES(?,?,?,"admin")');$s->execute([$name,$username,password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['user_id']=$pdo->lastInsertId();$_SESSION['user_name']=$name;$_SESSION['role']='admin';go('dashboard');}
 flash('Complete all fields. Password must be at least 6 characters.','error');go('register');
}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['role']=$u['role'];go('dashboard');}flash('Incorrect username or password.','error');go('login');}
if($page!=='login'&&$page!=='register')require_login();
// Actions
if($_SERVER['REQUEST_METHOD']==='POST' && !in_array($page,['login','register'])){
 try{
  if($page==='products'&&isset($_POST['save'])){$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['sku'])?:null,trim($_POST['category'])?:'General',trim($_POST['description']),max(0,(float)$_POST['cost']),max(0,(float)$_POST['price']),max(0,(int)$_POST['stock']),max(0,(int)$_POST['low_stock'])];if($id){$d[]=$id;$pdo->prepare('UPDATE products SET name=?,sku=?,category=?,description=?,cost=?,price=?,stock=?,low_stock=? WHERE id=?')->execute($d);}else{$pdo->prepare('INSERT INTO products(name,sku,category,description,cost,price,stock,low_stock) VALUES(?,?,?,?,?,?,?,?)')->execute($d);}flash('Product saved.');go('products');}
  if($page==='products'&&isset($_POST['delete'])){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['id']]);flash('Product deleted.');go('products');}
  if($page==='customers'&&isset($_POST['save'])){$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])];if($id){$d[]=$id;$pdo->prepare('UPDATE customers SET name=?,phone=?,email=?,address=? WHERE id=?')->execute($d);}else $pdo->prepare('INSERT INTO customers(name,phone,email,address) VALUES(?,?,?,?)')->execute($d);flash('Customer saved.');go('customers');}
  if($page==='customers'&&isset($_POST['delete'])){$pdo->prepare('DELETE FROM customers WHERE id=?')->execute([(int)$_POST['id']]);flash('Customer deleted.');go('customers');}
  if($page==='suppliers'&&isset($_POST['save'])){$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['contact_person']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address'])];if($id){$d[]=$id;$pdo->prepare('UPDATE suppliers SET name=?,contact_person=?,phone=?,email=?,address=? WHERE id=?')->execute($d);}else $pdo->prepare('INSERT INTO suppliers(name,contact_person,phone,email,address) VALUES(?,?,?,?,?)')->execute($d);flash('Supplier saved.');go('suppliers');}
  if($page==='suppliers'&&isset($_POST['delete'])){$pdo->prepare('DELETE FROM suppliers WHERE id=?')->execute([(int)$_POST['id']]);flash('Supplier deleted.');go('suppliers');}
  if($page==='sales'&&isset($_POST['checkout'])){$items=$_POST['qty']??[];$pdo->beginTransaction();$lines=[];$total=0;foreach($items as $pid=>$qty){$qty=(int)$qty;if($qty<1)continue;$s=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$s->execute([(int)$pid]);$p=$s->fetch();if(!$p||$p['stock']<$qty)throw new Exception('Not enough stock for '.($p['name']??'a product').'.');$sub=$p['price']*$qty;$total+=$sub;$lines[]=[$p,$qty,$sub];}if(!$lines)throw new Exception('Add at least one item to the sale.');$receipt='R'.date('YmdHis').random_int(10,99);$customer=(int)($_POST['customer_id']??0)?:null;$pdo->prepare('INSERT INTO sales(receipt_no,customer_id,total,payment_method,sold_by) VALUES(?,?,?,?,?)')->execute([$receipt,$customer,$total,$_POST['payment_method']??'Cash',$_SESSION['user_id']]);$sid=$pdo->lastInsertId();foreach($lines as [$p,$q,$sub]){$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,subtotal) VALUES(?,?,?,?,?,?)')->execute([$sid,$p['id'],$p['name'],$q,$p['price'],$sub]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$q,$p['id']]);}$pdo->commit();flash("Sale completed. Receipt: $receipt");go('sales');}
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex->getMessage(),'error');go($page);}
}
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
function rows($pdo,$sql,$args=[]){$s=$pdo->prepare($sql);$s->execute($args);return $s->fetchAll();}
$edit=null;if(isset($_GET['edit'])){$table=['products'=>'products','customers'=>'customers','suppliers'=>'suppliers'][$page]??null;if($table){$s=$pdo->prepare("SELECT * FROM $table WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}}
