<?php if(in_array($page,['login','register'])): ?><main class="auth-wrap"><section class="auth-card"><div class="brand-mark">CL</div><p class="eyebrow">CLEARLEDGER</p><h1><?= $page==='register'?'Set up your workspace':'Welcome back' ?></h1><p class="muted"><?= $page==='register'?'Create the first administrator account to get started.':'Sign in to manage your business.' ?></p><?php if($flash):?><div class="alert <?=e($flash['t'])?>"><?=e($flash['m'])?></div><?php endif;?><form method="post" action="index.php?page=<?=$page?>"><?php if($page==='register'):?><label>Your name</label><input name="name" required placeholder="e.g. Alex Santos"><?php endif;?><label>Username</label><input name="username" required autocomplete="username" placeholder="Enter your username"><label>Password</label><input type="password" name="password" required minlength="6" autocomplete="current-password" placeholder="Enter your password"><button class="btn primary full"><?=$page==='register'?'Create workspace':'Sign in'?></button></form><?php if($page==='login'&&(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()===0):?><p class="small center">First time here? <a href="index.php?page=register">Set up your workspace</a></p><?php endif;?></section></main>
