<?php if($page==='dashboard'):
$today=(float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=CURDATE()')->fetchColumn();$month=(float)$pdo->query('SELECT COALESCE(SUM(total),0) FROM sales WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())')->fetchColumn();$products=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$low=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock<=low_stock')->fetchColumn();$recent=rows($pdo,'SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id ORDER BY s.id DESC LIMIT 6');?><div class="welcome"><div><h1>Good day, <?=e(explode(' ',$_SESSION['user_name'])[0])?>!</h1><p>Here is what is happening in your business today.</p></div><a class="btn primary" href="index.php?page=sales">＋ Create a sale</a></div><div class="stats"><article class="stat"><span>Today's sales</span><strong><?=money($today)?></strong><small>Sales recorded today</small></article><article class="stat"><span>This month's sales</span><strong><?=money($month)?></strong><small>Month-to-date total</small></article><article class="stat"><span>Products</span><strong><?=$products?></strong><small>Items in your catalog</small></article><article class="stat"><span>Low stock alerts</span><strong><?=$low?></strong><small>Items that may need restocking</small></article></div><section class="panel"><div class="panel-head"><div><h3>Recent sales</h3><p>Your latest completed transactions</p></div><a href="index.php?page=reports" class="text-link">View reports →</a></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Date</th><th>Payment</th><th class="right">Total</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><b><?=e($r['receipt_no'])?></b></td><td><?=e($r['customer']??'Walk-in customer')?></td><td><?=e(date('M j, Y g:i A',strtotime($r['created_at'])))?></td><td><?=e($r['payment_method'])?></td><td class="right"><?=money($r['total'])?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5" class="empty">No sales yet. Create your first sale to see it here.</td></tr><?php endif;?></tbody></table></div></section>
<?php elseif($page==='products'):?><div class="page-grid"><section class="panel form-panel"><div class="panel-head"><div><h3><?=$edit?'Edit product':'Add a product'?></h3><p>Enter the details of an item you sell.</p></div></div><form method="post"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Product name *</label><input name="name" required value="<?=e($edit['name']??'')?>" placeholder="e.g. Notebook"><div class="two"><div><label>SKU / Code</label><input name="sku" value="<?=e($edit['sku']??'')?>" placeholder="Optional"></div><div><label>Category</label><input name="category" value="<?=e($edit['category']??'General')?>" placeholder="General"></div></div><label>Description</label><textarea name="description" rows="2" placeholder="Short product details"><?=e($edit['description']??'')?></textarea><div class="two"><div><label>Cost price (₱)</label><input type="number" min="0" step="0.01" name="cost" value="<?=e($edit['cost']??'0')?>"></div><div><label>Selling price (₱) *</label><input type="number" min="0" step="0.01" name="price" required value="<?=e($edit['price']??'0')?>"></div></div><div class="two"><div><label>Quantity in stock</label><input type="number" min="0" name="stock" value="<?=e($edit['stock']??'0')?>"></div><div><label>Low stock warning at</label><input type="number" min="0" name="low_stock" value="<?=e($edit['low_stock']??'5')?>"></div></div><button class="btn primary" name="save">Save product</button><?php if($edit):?><a class="btn light" href="index.php?page=products">Cancel</a><?php endif;?></form></section><section class="panel"><div class="panel-head"><div><h3>Product list</h3><p>All products in your catalog</p></div><input class="search" placeholder="Search products..." oninput="filterRows(this,'product-table')"></div><div class="table-wrap"><table id="product-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><?php foreach(rows($pdo,'SELECT * FROM products ORDER BY name') as $p):?><tr><td><b><?=e($p['name'])?></b><small class="subcell"><?=e($p['sku']??'No code')?></small></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><span class="pill <?=$p['stock']<=$p['low_stock']?'warning':'good'?>"><?=$p['stock']<=$p['low_stock']?'Low stock':'In stock'?></span></td><td class="actions"><a href="index.php?page=products&edit=<?=$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="delete" class="link-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div>
