<?php elseif($page==='reports'):$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$list=rows($pdo,'SELECT s.*,c.name customer,u.name staff FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.sold_by WHERE DATE(s.created_at) BETWEEN ? AND ? ORDER BY s.created_at DESC',[$from,$to]);$sum=array_sum(array_column($list,'total'));?><section class="panel"><div class="panel-head"><div><h3>Sales report</h3><p>Review completed sales for a selected date range.</p></div><form class="date-filter" method="get"><input type="hidden" name="page" value="reports"><input type="date" name="from" value="<?=e($from)?>"><span>to</span><input type="date" name="to" value="<?=e($to)?>"><button class="btn primary">Apply</button></form></div><div class="report-total"><span>Total sales in this period</span><strong><?=money($sum)?></strong><small><?=count($list)?> completed transactions</small></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Date</th><th>Customer</th><th>Staff</th><th>Payment</th><th class="right">Total</th></tr></thead><tbody><?php foreach($list as $r):?><tr><td><b><?=e($r['receipt_no'])?></b></td><td><?=e(date('M j, Y g:i A',strtotime($r['created_at'])))?></td><td><?=e($r['customer']??'Walk-in customer')?></td><td><?=e($r['staff']??'—')?></td><td><?=e($r['payment_method'])?></td><td class="right"><?=money($r['total'])?></td></tr><?php endforeach;?><?php if(!$list):?><tr><td colspan="6" class="empty">No sales found for these dates.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?></div></main></div><?php endif;?>
